def svc(*names):  # a simple menu for the live example: [(section, [(name, price)])]
    return [{"n": s, "items": [{"n": n, "p": p, "d": "", "b": i == 0, "i": ""} for i, (n, p) in enumerate(items)]} for s, items in names]

